<script setup>
import { computed, ref, watch } from 'vue'
import { Activity, AlertTriangle, ArrowDown, ArrowRight, BookOpen, Brain, Check, ChevronRight, Clock3, Code2, Database, FileJson2, Layers3, LockKeyhole, Search, ShieldCheck, Sparkles, SlidersHorizontal, WandSparkles, X } from 'lucide-vue-next'

const sources = ref([
  { id: 'persona', name: '系统提示词 / persona', description: '系统身份、安全基线与输出约定', layer: '企业级', scope: '全部作用域', tokens: 820, compressed: false, included: true, protected: true, order: 1, preview: '你是当前工作空间中的编码代理，遵循授权边界并以证据验证变更。' },
  { id: 'project', name: '项目指令文件', description: 'AGENTS.md / 项目协作规则', layer: '项目级', scope: '全部作用域', tokens: 620, compressed: false, included: true, protected: true, order: 2, preview: '遵守仓库约定；提交前运行相关验证；一次变更只处理一个明确目标。' },
  { id: 'history', name: '会话历史', description: '滑动窗口内的历史轮次与近期对话', layer: '会话级', scope: '会话', tokens: 4820, compressed: true, included: true, protected: false, order: 9, preview: '近期对话摘要与最近 6 轮原文，保留当前任务的关键约束。' },
  { id: 'retrieval', name: '检索结果', description: '带来源引用的相关片段，视为不可信输入', layer: '会话级', scope: '会话', tokens: 3140, compressed: true, included: true, protected: false, order: 8, preview: '[1] 架构说明文档 · [2] 上下文预算测试 · 共 5 条片段。' },
  { id: 'skills', name: '技能定义', description: '按需激活的技能正文与简短描述', layer: '目录级', scope: 'Agent / 会话', tokens: 1450, compressed: true, included: true, protected: false, order: 3, preview: '命中技能后注入正文；未命中时只保留名称和描述。' },
  { id: 'tools', name: '工具接口定义', description: '当前智能体可调用的工具说明', layer: '智能体级', scope: '智能体 / 会话', tokens: 2260, compressed: true, included: true, protected: false, order: 5, preview: '读取文件 · 写入文件 · 执行命令 · 网页搜索 · …' },
  { id: 'workspace', name: '工作空间状态', description: '当前目录、分支与工作区摘要', layer: '工作空间级', scope: '工作空间', tokens: 180, compressed: true, included: true, protected: false, order: 7, preview: '当前目录：工作空间根目录 · 当前分支：主分支 · 工作区：运行中' },
  { id: 'preferences', name: '用户自定义指令', description: '用户偏好与跨会话约定', layer: '用户级', scope: 'Agent / 会话', tokens: 240, compressed: true, included: true, protected: false, order: 4, preview: '中文回复；代码注释保持英文；优先小步验证。' },
  { id: 'runtime', name: '运行环境信息', description: '智能体、模型与任务目标摘要', layer: '会话级', scope: '会话', tokens: 120, compressed: true, included: true, protected: false, order: 6, preview: '智能体：工作空间助手 · 模型：当前已选 · 任务：正在处理' },
])

const scopeOptions = [
  { id: 'all', label: '全部来源', description: '查看完整上下文' },
  { id: 'workspace', label: '工作空间', description: '工作空间级绑定' },
  { id: 'agent', label: '开发助手 04', description: '智能体级绑定' },
  { id: 'session', label: '当前会话', description: '本次对话' },
]
const views = [
  { id: 'assembly', letter: 'A', label: '组装', icon: Layers3 },
  { id: 'layers', letter: 'B', label: '分层', icon: Layers3 },
  { id: 'budget', letter: 'C', label: '预算', icon: Activity },
  { id: 'compression', letter: 'D', label: '压缩', icon: ArrowDown },
  { id: 'retrieval', letter: 'E', label: '检索', icon: Search },
  { id: 'memory', letter: 'F', label: '记忆', icon: Brain },
  { id: 'state', letter: 'G', label: '中间态', icon: Code2 },
  { id: 'isolation', letter: 'H', label: '隔离', icon: LockKeyhole },
  { id: 'security', letter: '', label: '安全', icon: ShieldCheck },
  { id: 'viewer', letter: 'J', label: '查看器', icon: FileJson2 },
  { id: 'maturity', letter: '', label: '成熟度', icon: Sparkles },
]
const scope = ref('all')
const activeView = ref('assembly')
const retrievalQuery = ref('')
const compressionMode = ref('按需压缩')
const protectRecentTurns = ref(true)
const preserveDecisions = ref(true)
const memoryPolicies = ref({ reusableFacts: true, periodicNotes: true, sensitiveContent: false })
const toast = ref('')
const compressedCount = ref(0)
const memoryCount = ref(126)
const retrievalItems = ref([
  { id: 'r1', title: 'docs/architecture.md#L42', text: '鉴权令牌刷新与会话缓存的竞态处理约定。', score: 0.94, tokens: 684, included: true },
  { id: 'r2', title: 'tests/auth-refresh.spec.ts#L18', text: '覆盖并发刷新与过期令牌恢复的回归测试。', score: 0.88, tokens: 612, included: true },
  { id: 'r3', title: 'docs/troubleshooting.md#L106', text: '登录请求出现 401 时的排查步骤和日志字段。', score: 0.81, tokens: 744, included: true },
  { id: 'r4', title: 'notes/old-auth-plan.md#L9', text: '历史方案草稿，内容未经过当前项目规则验证。', score: 0.57, tokens: 522, included: false },
])
const enabledSources = computed(() => sources.value.filter(source => source.included && sourceInScope(source)))
const orderedSources = computed(() => [...enabledSources.value].sort((a, b) => a.order - b.order))
const activeSourceCount = computed(() => enabledSources.value.length)
const totalTokens = computed(() => enabledSources.value.reduce((sum, source) => sum + source.tokens, 0))
const windowTokens = 32000
const outputReserve = 4096
const inputBudget = windowTokens - outputReserve
const usagePercent = computed(() => Number((totalTokens.value / inputBudget * 100).toFixed(1)))
const softThreshold = Math.round(inputBudget * 0.7)
const hardThreshold = Math.round(inputBudget * 0.9)
const remainingTokens = computed(() => inputBudget - totalTokens.value)
const enabledRetrievalTokens = computed(() => retrievalItems.value.filter(item => item.included).reduce((sum, item) => sum + item.tokens, 0))
const filteredRetrievalItems = computed(() => retrievalItems.value.filter(item => `${item.title} ${item.text}`.toLowerCase().includes(retrievalQuery.value.trim().toLowerCase()) || !retrievalQuery.value.trim()))
const contextEvents = ref([
  { time: '14:02:11', title: '组装完成', detail: '9 个来源 · 13,650 tok', tone: 'green' },
  { time: '14:01:52', title: '检索完成', detail: '6 条候选 → 保留 5 条 · 3,140 tok', tone: 'blue' },
  { time: '14:01:30', title: '技能命中', detail: 'pdf-extract 正文注入 · 1,450 tok', tone: 'coral' },
])

watch(scope, value => {
  contextEvents.value.unshift({ time: '刚刚', title: '作用域已切换', detail: `${scopeOptions.find(item => item.id === value)?.label} · ${activeSourceCount.value} 个来源`, tone: 'coral' })
  contextEvents.value = contextEvents.value.slice(0, 3)
})

function notify(message) {
  toast.value = message
  window.clearTimeout(notify.timer)
  notify.timer = window.setTimeout(() => { toast.value = '' }, 2400)
}
function sourceInScope(source) {
  if (scope.value === 'all' || source.scope === '全部作用域') return true
  if (scope.value === 'workspace') return source.scope === '工作空间'
  if (scope.value === 'agent') return ['Agent / 会话', '工作空间'].includes(source.scope)
  return source.scope !== '工作空间'
}
function toggleSource(source) {
  if (source.protected) return
  source.included = !source.included
}
function runCompression() {
  const history = sources.value.find(source => source.id === 'history')
  if (!history.included || history.tokens <= 1800) {
    notify('当前没有可压缩的会话历史')
    return
  }
  const before = history.tokens
  history.tokens = Math.max(1800, Math.round(history.tokens * 0.58))
  compressedCount.value += 1
  contextEvents.value.unshift({ time: '刚刚', title: '压缩完成', detail: `会话历史 ${before.toLocaleString()} → ${history.tokens.toLocaleString()} tok`, tone: 'green' })
  contextEvents.value = contextEvents.value.slice(0, 3)
  notify(`会话历史已压缩，减少 ${(before - history.tokens).toLocaleString()} tokens（演示）`)
}
function consolidateMemory() {
  memoryCount.value += 8
  notify('结构化记忆已巩固（演示）')
}
function formatNumber(value) {
  return value.toLocaleString('en-US')
}
</script>

<template>
  <section class="context-engineering-page">
    <header class="context-page-heading">
      <div><h1>上下文工程</h1><p>组装、分层、预算、压缩、检索、记忆与中间态</p></div>
      <div class="context-scopes" role="tablist" aria-label="上下文作用域">
        <button v-for="item in scopeOptions" :key="item.id" role="tab" :aria-selected="scope === item.id" :title="item.description" :class="{ active: scope === item.id }" @click="scope = item.id">{{ item.label }}</button>
      </div>
    </header>

    <div class="context-kpis">
      <div><strong>{{ usagePercent }}%</strong><span>窗口占用</span></div>
      <div><strong>{{ formatNumber(totalTokens) }}</strong><span>已用 token</span></div>
      <div><strong>{{ activeSourceCount }}<small> / {{ scope === 'all' ? 9 : 9 }}</small></strong><span>注入来源</span></div>
      <div><strong>{{ compressedCount }}</strong><span>压缩次数</span></div>
      <div><strong :class="usagePercent >= 90 ? 'danger' : usagePercent >= 70 ? 'warning' : ''">{{ usagePercent >= 70 ? 1 : 0 }}</strong><span>预算告警</span></div>
    </div>

    <div class="context-workbench">
      <aside class="context-sources-panel">
        <header class="context-panel-heading"><div><h2>上下文来源</h2><span>{{ activeSourceCount }} / 9 开启</span></div><SlidersHorizontal :size="15" /></header>
        <div class="source-list">
          <div v-for="source in sources" :key="source.id" class="context-source" :class="{ disabled: !source.included, outscope: !sourceInScope(source) }">
            <label class="source-toggle" :title="source.protected ? '此来源由更高层级策略固定' : '切换来源注入状态'"><input type="checkbox" :checked="source.included" :disabled="source.protected" @change="toggleSource(source)"><span class="toggle-box"><Check v-if="source.included" :size="11" /></span><strong>{{ source.name }}</strong></label>
            <span class="source-token">{{ formatNumber(source.tokens) }}</span>
            <p>{{ source.description }}</p>
            <div class="source-meta"><span>{{ source.layer }}</span><i></i><span :class="source.protected ? 'locked' : source.compressed ? 'compressible' : 'locked'">{{ source.protected ? '不可覆盖' : source.compressed ? '可压缩' : '固定保留' }}</span><span v-if="!sourceInScope(source)">不在当前作用域</span></div>
            <div class="source-meter"><i :style="{ width: `${Math.min(source.tokens / 5000 * 100, 100)}%` }" :class="`meter-${source.id}`"></i></div>
          </div>
        </div>
        <footer class="source-footer"><span>已注入 <b>{{ formatNumber(totalTokens) }}</b></span><span>剩余 <b class="remaining">{{ formatNumber(remainingTokens) }}</b></span><button :disabled="!sources.some(source => source.included && source.compressed)" @click="activeView = 'compression'">裁剪</button></footer>
      </aside>

      <main class="context-center-panel">
        <nav class="context-view-tabs" aria-label="上下文工程视图">
          <button v-for="view in views" :key="view.id" :class="{ active: activeView === view.id }" @click="activeView = view.id"><span v-if="view.letter">{{ view.letter }}</span>{{ view.label }}</button>
        </nav>

        <div v-if="activeView === 'assembly'" class="context-view-content">
          <div class="assembly-columns">
            <section class="context-subpanel assembly-pipeline"><header><div><h2>组装流水线</h2><span>{{ activeSourceCount }} 段 · 按注入顺序</span></div><b class="scope-caption">{{ scopeOptions.find(item => item.id === scope)?.label }} · {{ formatNumber(totalTokens) }} tok</b></header>
              <div class="pipeline-meter"><i v-for="source in orderedSources" :key="source.id" :class="`meter-${source.id}`" :style="{ flexGrow: source.tokens }"></i></div>
              <div class="pipeline-table-wrap"><table class="pipeline-table"><thead><tr><th>#</th><th>来源</th><th>层级</th><th>token</th><th>区间</th><th>占比</th></tr></thead><tbody><tr v-for="(source,index) in orderedSources" :key="source.id"><td>{{ String(index + 1).padStart(2,'0') }}</td><td><span class="source-color" :class="`meter-${source.id}`"></span>{{ source.name }}</td><td>{{ source.layer }}</td><td>{{ formatNumber(source.tokens) }}</td><td>{{ formatNumber(orderedSources.slice(0,index).reduce((sum,item)=>sum+item.tokens,0)) }}–{{ formatNumber(orderedSources.slice(0,index+1).reduce((sum,item)=>sum+item.tokens,0)) }}</td><td>{{ (source.tokens / Math.max(totalTokens,1) * 100).toFixed(1) }}%</td></tr></tbody></table></div>
              <p class="panel-note">注入顺序固定为系统 → 项目 → 目录 → 用户 → 工具 → 环境 → 工作空间 → 检索 → 历史。前置规则优先级更高；检索片段按不可信输入处理。</p>
            </section>
            <div class="assembly-side-stack">
              <section class="context-subpanel scope-matrix"><header><div><h2>作用域隔离</h2><span>来源绑定边界</span></div></header><div class="scope-matrix-table"><div class="matrix-row matrix-head"><span>来源</span><span>工作区</span><span>Agent</span><span>会话</span></div><div v-for="source in sources" :key="source.id" class="matrix-row"><span>{{ source.name }}</span><span :class="{ bound: ['全部作用域','工作空间'].includes(source.scope) }">{{ ['全部作用域','工作空间'].includes(source.scope) ? '●' : '○' }}</span><span :class="{ bound: ['全部作用域','Agent / 会话','工作空间'].includes(source.scope) }">{{ ['全部作用域','Agent / 会话','工作空间'].includes(source.scope) ? '●' : '○' }}</span><span :class="{ bound: source.scope !== '工作空间' }">{{ source.scope !== '工作空间' ? '●' : '○' }}</span></div></div><p class="panel-note">同一份上下文不跨作用域串用。当前视图仅统计匹配作用域并已开启的来源。</p></section>
              <section class="context-subpanel dynamic-injection"><header><div><h2>动态启用</h2><span>技能 / MCP 按需</span></div><Sparkles :size="14" /></header><div class="activation-row"><b>pdf-extract</b><span class="activation-hit">命中 · 注入正文</span><small>1,450</small></div><div class="activation-row"><b>sheet-agent</b><span class="activation-hit">命中 · 注入正文</span><small>860</small></div><div class="activation-row"><b>legal-review</b><span class="activation-miss">未命中 · 仅 name+desc</span><small>48</small></div><div class="activation-row"><b>image-gen</b><span class="activation-miss">未命中 · 仅 name+desc</span><small>36</small></div><p class="panel-note">未命中技能只注入简短描述，命中后才加载全文，避免全量常驻占用预算。</p></section>
            </div>
          </div>
          <section class="context-subpanel assembled-preview"><header><div><h2>装配预览</h2><span>按注入顺序 · 实际上下文骨架</span></div><button class="context-quiet-button" @click="notify('上下文骨架已复制（演示）')"><Code2 :size="13" />复制骨架</button></header><div class="preview-lines"><div v-for="source in orderedSources" :key="source.id"><code>&lt;{{ source.id }}&gt;</code><span>{{ source.preview }}</span><small>{{ formatNumber(source.tokens) }}</small></div></div><footer>合计 <b>{{ formatNumber(totalTokens) }}</b> / {{ formatNumber(inputBudget) }} tok <strong>{{ usagePercent }}%</strong></footer></section>
        </div>

        <div v-else-if="activeView === 'layers'" class="context-view-content"><div class="view-intro"><h2>上下文分层</h2><p>按信任等级与生命周期安排内容。系统和项目规则优先级最高，历史对话和检索内容更容易被裁剪。</p></div><div class="layer-list"><div v-for="(layer,index) in [{name:'企业级',trust:'最高信任',color:'layer-enterprise',items:['系统提示词 / persona'],rule:'不可压缩 · 会话内不可覆盖'},{name:'项目级',trust:'高信任',color:'layer-project',items:['项目指令文件'],rule:'不可压缩 · 仓库策略固定'},{name:'Agent 与用户级',trust:'显式配置',color:'layer-agent',items:['技能定义','工具 Schema','用户自定义指令'],rule:'按 Agent 能力裁剪 · 可调整注入'},{name:'会话级',trust:'动态内容',color:'layer-session',items:['运行环境信息','检索结果','会话历史'],rule:'滚动更新 · 可摘要和压缩'}]" :key="layer.name"><i :class="layer.color"></i><div><b>{{ layer.name }}</b><small>{{ layer.trust }}</small></div><span>{{ layer.items.join(' · ') }}</span><strong>{{ layer.rule }}</strong></div></div><div class="trust-callout"><ShieldCheck :size="16" /><span>检索结果来自外部或用户内容，应作为不可信数据引用；不能覆盖系统与项目级指令。</span></div></div>

        <div v-else-if="activeView === 'budget'" class="context-view-content"><div class="view-intro"><h2>预算与计量</h2><p>按模型窗口容量计算可用输入预算，并为输出预留空间。占用超过阈值时先规划压缩。</p></div><div class="budget-summary"><div><span>上下文窗口</span><strong>{{ formatNumber(windowTokens) }} tok</strong></div><div><span>预留输出空间</span><strong>{{ formatNumber(outputReserve) }} tok</strong></div><div><span>可用输入预算</span><strong>{{ formatNumber(inputBudget) }} tok</strong></div><div><span>已注入</span><strong>{{ formatNumber(totalTokens) }} tok</strong></div><div><span>剩余</span><strong class="positive-value">{{ formatNumber(remainingTokens) }} tok</strong></div></div><div class="budget-scale"><div><span>当前占用</span><b>{{ usagePercent }}%</b></div><div class="budget-bar"><i :style="{width:`${Math.min(usagePercent,100)}%`}"></i><span :style="{left:'70%'}"></span><span :style="{left:'90%'}"></span></div><div class="budget-thresholds"><span>0</span><span>70% 软阈值 · {{ formatNumber(softThreshold) }}</span><span>90% 硬阈值 · {{ formatNumber(hardThreshold) }}</span></div></div><h3 class="subsection-title">来源占比</h3><div class="distribution-list"><div v-for="source in [...orderedSources].sort((a,b)=>b.tokens-a.tokens)" :key="source.id"><span class="source-color" :class="`meter-${source.id}`"></span><b>{{ source.name }}</b><div class="distribution-track"><i :style="{width:`${source.tokens/Math.max(totalTokens,1)*100}%`}" :class="`meter-${source.id}`"></i></div><strong>{{ (source.tokens/Math.max(totalTokens,1)*100).toFixed(1) }}%</strong><small>{{ formatNumber(source.tokens) }}</small></div></div></div>

        <div v-else-if="activeView === 'compression'" class="context-view-content"><div class="view-intro"><h2>压缩策略</h2><p>保护当前任务目标与最近用户输入，优先摘要较早历史和低相关检索片段。</p></div><div class="compression-controls"><label>压缩模式<select v-model="compressionMode"><option>按需压缩</option><option>阈值触发</option><option>每轮摘要</option></select></label><div class="threshold-setting"><span>软阈值</span><strong>70%</strong><span>硬阈值</span><strong>90%</strong></div><label class="compress-switch"><input v-model="protectRecentTurns" type="checkbox"><span>保护最近 6 轮和当前任务说明</span></label><label class="compress-switch"><input v-model="preserveDecisions" type="checkbox"><span>摘要后保留引用与关键决定</span></label><button class="context-primary-button" @click="runCompression"><WandSparkles :size="14" />模拟压缩会话历史</button></div><h3 class="subsection-title">压缩前后估算</h3><div class="compression-comparison"><div><span>压缩前</span><strong>{{ formatNumber(totalTokens) }} tok</strong></div><ArrowRight :size="15" /><div><span>预计压缩后</span><strong>{{ formatNumber(Math.max(totalTokens - Math.round(sources.find(source=>source.id==='history').tokens*.42),0)) }} tok</strong></div><div class="compression-savings">按需生成摘要，保留最近对话细节</div></div><div class="protection-note"><LockKeyhole :size="15" />不可压缩来源：系统提示词、项目指令文件；始终保留原始策略。</div></div>

        <div v-else-if="activeView === 'retrieval'" class="context-view-content"><div class="view-intro"><h2>检索与重排</h2><p>检索候选经过权限过滤、相关度重排和预算裁剪后才注入会话。</p></div><label class="retrieval-search"><Search :size="15" /><input v-model="retrievalQuery" aria-label="检索查询" placeholder="输入检索查询" /><span>Top 5</span></label><div class="retrieval-stats"><span>召回 6 条</span><ArrowRight :size="13" /><span>重排保留 {{ retrievalItems.filter(item=>item.included).length }} 条</span><b>{{ formatNumber(enabledRetrievalTokens) }} tok</b></div><div class="retrieval-list"><article v-for="item in filteredRetrievalItems" :key="item.id" :class="{ excluded: !item.included }"><label><input v-model="item.included" type="checkbox"><span class="retrieval-check"><Check :size="11" /></span></label><div><header><strong>{{ item.title }}</strong><span :class="item.included?'trust-untrusted':'trust-muted'">{{ item.included?'不可信片段':'未注入' }}</span></header><p>{{ item.text }}</p><footer><span>相关度 {{ item.score.toFixed(2) }}</span><span>{{ item.tokens }} tok</span></footer></div></article><div v-if="!filteredRetrievalItems.length" class="empty-view">没有匹配片段，试试更短的查询词。</div></div><div class="trust-callout"><AlertTriangle :size="15" /><span>召回内容仅作为证据和引用来源，不可覆盖系统、项目或用户明确指令。</span></div></div>

        <div v-else-if="activeView === 'memory'" class="context-view-content"><div class="view-intro"><h2>记忆与巩固</h2><p>区分会话工作记忆、工作空间文件记忆和长期用户偏好，并保留来源与作用域。</p></div><div class="memory-rows"><div><Database :size="16"/><span><b>会话工作记忆</b><small>当前运行 · 临时状态与待办</small></span><strong>18 个字段</strong><button @click="notify('会话记忆仅在演示视图中查看')">查看</button></div><div><BookOpen :size="16"/><span><b>工作空间记忆</b><small>仓库级摘要 · 变更后重新索引</small></span><strong>notes.md · 2.4 KB</strong><button @click="notify('工作空间记忆仅在演示视图中查看')">查看</button></div><div><Brain :size="16"/><span><b>长期偏好记忆</b><small>用户级 · 冲突时服从更高优先级规则</small></span><strong>{{ memoryCount }} 条</strong><button @click="consolidateMemory">巩固</button></div></div><div class="memory-policy"><h3>记忆写入策略</h3><label><input v-model="memoryPolicies.reusableFacts" type="checkbox">只沉淀可复用事实与明确偏好</label><label><input v-model="memoryPolicies.periodicNotes" type="checkbox">每 8 轮整理一次结构化笔记</label><label><input v-model="memoryPolicies.sensitiveContent" type="checkbox">敏感内容不进入长期记忆</label></div></div>

        <div v-else-if="activeView === 'state'" class="context-view-content"><div class="view-intro"><h2>运行中间态</h2><p>结构化任务状态让长运行可检查、可恢复，不依赖反复重读完整对话。</p></div><div class="state-toolbar"><span>RUN-2048 · session state</span><button class="context-quiet-button" @click="notify('中间态快照已复制（演示）')"><Code2 :size="13"/>复制 JSON</button></div><pre class="state-json">{
  "goal": "分析退款异常并给出证据",
